Below is a simple Vega-Lite specification for a bar chart that reads a CSV (data.csv) with columns "option" and "count" and plots counts by answer option.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "data.csv",
    "format": {
      "type": "csv"
    }
  },
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "option",
      "type": "nominal",
      "axis": {
        "title": "Option",
        "labelAngle": 0
      }
    },
    "y": {
      "field": "count",
      "type": "quantitative",
      "axis": {
        "title": "Count"
      }
    },
    "tooltip": [
      {
        "field": "option",
        "type": "nominal",
        "title": "Option"
      },
      {
        "field": "count",
        "type": "quantitative",
        "title": "Count"
      }
    ]
  },
  "width": 500,
  "height": 300
}
```

